const waitForResyncLog = async (logId, fechaInicio, fechaFin) => {
  const maxPolls = 240; // hasta ~10 minutos
  for (let attempt = 0; attempt < maxPolls; attempt += 1) {
    if (attempt > 0) await new Promise((resolve) => setTimeout(resolve, 2500));
    const statusRes = await apiGet(`/admin/scheduler/resync/status/${logId}`);
    if (statusRes.estado !== ESTADO.OK) {
      if (attempt >= 4) throw new Error(statusRes.mensaje || 'No se pudo consultar el avance de la sincronización.');
      continue;
    }
    const statusData = statusRes.data || {};
    if (statusData.terminal) {
      if (statusData.job_success) return true;
      throw new Error(statusData.message || `No se pudo completar la sincronización para ${fechaInicio} a ${fechaFin}`);
    }
    setSyncMessage({
      tipo: 'info',
      texto: `Sincronizando detalle ISCAM ${fechaInicio} a ${fechaFin}...`,
    });
  }
  setSyncMessage({
    tipo: 'info',
    texto: `La sincronización ${fechaInicio} a ${fechaFin} continúa en segundo plano.`,
  });
  return false;
};

const syncMissingClosedDays = async () => {
  const headerGap = Boolean(freshness?.stale);
  const detailGap = Boolean(freshness?.detail_stale);
  const detailOnly = detailGap && !headerGap;
  const syncFrom = detailOnly
    ? freshness?.detail_missing_from
    : (freshness?.missing_from || freshness?.detail_missing_from);
  const syncTo = detailOnly
    ? freshness?.detail_missing_to
    : (freshness?.missing_to || freshness?.detail_missing_to);
  if (!(headerGap || detailGap) || !syncFrom || !syncTo || syncing) return;
  setSyncing(true);
  setSyncMessage(null);
  try {
    const chunks = splitDateChunks(syncFrom, syncTo, 30);
    let allCompleted = true;
    for (const [fechaInicio, fechaFin] of chunks) {
      const basePayload = {
        tipo_sync: 'comercial_ventas_cerradas',
        unidad_negocio_id: unidad,
        fecha_inicio: fechaInicio,
        fecha_fin: fechaFin,
        motivo: detailOnly ? 'ISCAM sincronizar detalle faltante' : 'ISCAM sincronizar dias cerrados faltantes',
        detail_only: detailOnly,
      };
      const dry = await apiPost('/admin/scheduler/resync/execute', { ...basePayload, dry_run: true }, { timeout: 120000 });
      if (dry.estado !== ESTADO.OK || dry.data?.success !== true) {
        const dryError = dry.data?.error_message || dry.data?.resultado?.error_message || dry.data?.detail || dry.mensaje;
        throw new Error(dryError || `No se pudo validar la sincronización para ${fechaInicio} a ${fechaFin}`);
      }
      const real = await apiPost('/admin/scheduler/resync/execute', { ...basePayload, dry_run: false }, { timeout: detailOnly ? 30000 : 120000 });
      if (real.estado !== ESTADO.OK || real.data?.success !== true) {
        const realError = real.data?.error_message || real.data?.resultado?.error_message || real.data?.detail || real.mensaje;
        throw new Error(realError || `No se pudo iniciar la sincronización para ${fechaInicio} a ${fechaFin}`);
      }
      if (detailOnly && real.data?.resultado?.status === 'RUNNING') {
        const logId = real.data?.resultado?.resync_log_id;
        if (!logId) throw new Error('La sincronización inició sin identificador de seguimiento.');
        const completed = await waitForResyncLog(logId, fechaInicio, fechaFin);
        if (!completed) {
          allCompleted = false;
          break;
        }
      }
    }
    await Promise.all([fetchReport(), fetchFreshness()]);
    if (allCompleted) {
      setSyncMessage({
        tipo: 'ok',
        texto: detailOnly ? 'Detalle ISCAM sincronizado y validado.' : 'Sincronización de faltantes completada.',
      });
    }
  } catch (error) {
    setSyncMessage({ tipo: 'error', texto: error?.message || 'No se pudo sincronizar el rango faltante.' });
  } finally {
    setSyncing(false);
  }
};
